+      };
+
+      const result = await rnOndeviceAddonsToDeviceAddons.check({
+        packageManager,
+        mainConfig,
+        storybookVersion: '8.0.0',
+        storiesPaths: [],
+        hasCsfFactoryPreview: false,
+      });
